  'settings.connections.type': 'Tip',
  'settings.connections.typeHint': '„Niciuna” și „Directă” înseamnă lucruri diferite. „Niciuna” este inertă: nu numește nicio conexiune și nu este folosită niciodată, deci există doar până termini de completat rândul. „Directă” este o alegere reală: iese prin conexiunea proprie a acestui calculator și ocolește orice proxy pentru gazdele numite mai jos. Așa scoți un NAS de sub un proxy aplicat întregii aplicații. Un rând al cărui filtru se potrivește cu gazda bate un rând fără filtru, deci un rând direct cu filtru câștigă mereu în fața unui proxy care prinde tot.',
