  'settings.connections.filter': 'Filtru de gazde',
  'settings.connections.filterHint': 'O gazdă pe linie. Un domeniu simplu acoperă tot ce este sub el, deci example.org ajunge pentru dl2.example.org, iar * ? [ ] funcționează ca metacaractere. Gol înseamnă că acest rând prinde tot, ceea ce este mai slab decât un rând al cărui filtru se potrivește cu gazda.',
