  'settings.rules.thenHintFilter': 'O regulă care refuză reține linkul cu motivul ei. O regulă care acceptă merită și ea: pusă deasupra unui refuz larg, cu „Oprește-te la prima regulă care se potrivește” pornit, așa lași să treacă un singur hoster.',
