  'settings.rules.var.match': 'Grupul de captură N al tiparului „se potrivește cu tiparul” al acestei reguli pe FIELD. Acesta este <jd:source:N> din JDownloader, sub un nume care spune ce tipar citește. O regulă fără tipar potrivit pe acel câmp este refuzată la salvare, în loc să producă în tăcere un dosar numit <jd:match:url:1>.',
