  'settings.reconnect.command': 'Program',
  'settings.reconnect.commandHint': 'Calea completă a programului care se rulează. Pornește direct, nu printr-un shell, așa că o conductă, o redirectare sau două comenzi una după alta țin de metoda „Script”. %%router%%, %%username%%, %%password%% și %%ip%% sunt înlocuite înainte de pornire.',
  'settings.reconnect.args': 'Argumente',
