  'settings.reconnect.upnpState': 'Nu mai e nevoie de nimic. Gateway-ul se găsește întrebând rețeaua, așa că aceasta este metoda care merge fără să știi nimic despre router.',
  'settings.reconnect.upnpLocation': 'URL-ul de descriere al gateway-ului',
  'settings.reconnect.upnpLocationHint': 'Opțional și de regulă gol. Completează-l doar acolo unde căutarea multicast este filtrată, iar gateway-ul în sine se atinge perfect, lucru pe care descoperirea singură nu îl poate repara niciodată.',

  'settings.reconnect.interpreter': 'Interpretor',
