  'settings.reconnect.router': 'Adresa routerului',
  'settings.reconnect.routerHint': 'Routerul din rețeaua ta, fără schemă: 192.168.1.1, nu http://192.168.1.1/. În asta se transformă %%router%%. Nu este adresa publică, iar cele două nu trebuie schimbate niciodată între ele: o cerere de autentificare trimisă către cea publică scoate parola routerului tău pe internet.',
