  'settings.reconnect.checkTitle': 'Verificarea adresei',
  'settings.reconnect.checkUrl': 'URL pentru verificarea IP-ului',
  'settings.reconnect.checkUrlHint': 'Se accesează înainte ca metoda să ruleze și încă o dată după; rularea se consideră gata de îndată ce adresa afișată acolo s-a schimbat. Nu există o valoare implicită: un manager de descărcări găzduit de tine nu ar trebui să înceapă să-ți raporteze adresa unui serviciu pe care nu l-ai ales niciodată. Ce afișează trebuie să fie adresa pe care o vede internetul, fiindcă o pagină care întoarce adresa din propria ta rețea nu poate deosebi o reconectare de o rulare care n-a schimbat nimic.',
  'settings.reconnect.checkPresets': 'Servicii cunoscute',
