  'settings.reconnect.policyHint': 'Reconectările automate sunt declanșate într-un singur loc, iar pagina asta nu e acela. Una pornește când un motor de descărcare cere el însuși o nouă încercare după o pauză, fiindcă așa spune un hoster că limita ține de adresa asta. Nu rulează niciodată cât timp coada e oprită, fiindcă repornirea routerului rupe descărcările care încă merg. Nu rulează niciodată cât timp reconectarea nu e configurată complet. Rulează doar una odată: o a doua cerere așteaptă verdictul primeia, în loc să se bată cu ea pe router. Iar dacă adresa nu se mișcă, nu se grăbește nimic și se lasă să curgă așteptarea obișnuită dintre încercări.',

