  'settings.access.relay.title': 'Releul proiectului',
  'settings.access.relay.body': 'Un releu este un intermediar care face toate instanțele tale accesibile din afara rețelei de acasă, deci de oriunde. Acesta este pus la dispoziție gratuit de proiect.',
  'settings.access.relay.use': 'Folosește releul proiectului',
  'settings.access.relay.leadProject': 'Merge fără nicio configurare. Tot ce își spun instanțele tale este criptat, iar cheia o ai doar tu.',
  'settings.access.relay.seesButton': 'Ce vede?',
  'settings.access.relay.seesTip': 'Nevăzut de releu: linkurile tale, descărcările tale, fișierele tale și tokenul tău de acces.\n\nVăzut de releu: adresele IP ale instanțelor tale și când trimit ceva.\n\nAsta nu se poate ascunde prin criptare. Dacă te deranjează, ridică-ți propriul releu.',
