  'settings.access.ownRelay.containerLabel': 'Ca container separat',
  'settings.access.ownRelay.containerHint': 'Dacă niciuna dintre instanțele tale nu e accesibilă din exterior, releul trebuie să stea altundeva, pe serverul tău sau pe un VPS mic. Instalează containerul din Unraid Community Applications sau cu comanda de mai jos.\n\nContainerul nu are nevoie de configurare: pornește-l, scrie-i adresa mai sus, gata. Nu stochează nimic, deci nu ai ce salva.',
  'settings.access.tokens.title': 'Tokenuri API',
