  'settings.access.identity.title': 'Identitatea acestei instanțe',
  'settings.access.identity.nameLabel': 'Nume',
  'settings.access.identity.namePlaceholder': 'de ex. Server de acasă',
  'settings.access.identity.nameHint': 'Oferit primul la asociere și în codul QR de mai jos, în locul numelui pe care sistemul de operare sau mediul de rulare al containerului îl dă acestui calculator. Opțional: lasă gol ca să folosești în continuare acel nume.',
  'settings.access.identity.domainsLabel': 'Domenii cunoscute',
  'settings.access.identity.domainsHint': 'Fiecare domeniu este reținut automat prima dată când sosește o cerere prin el și rămâne listat aici chiar și atunci când cererile ulterioare vin prin IP-ul din LAN. Adaugă manual un domeniu dacă e deja configurat, dar încă n-a sosit nicio cerere prin el. O adresă completă pe rând, de ex. https://kl.example.com.',
  'settings.access.cardTitle': 'Conectarea instanțelor și acces la distanță',
  'settings.access.phrase.body': 'O singură frază leagă toate instanțele KnightLoader pe care le rulezi. Creeaz-o aici, apoi lipește-o în celelalte instanțe. Nu ai nevoie de cont sau autentificare și nu e nimic de configurat.',
  'settings.access.phrase.noPasswordWarning': 'Această instanță nu are parolă. Fraza ajunge la fiecare instanță pe care o conectezi cu ea, deci oricine o poate citi aici ajunge la toate, nu doar la aceasta. Mai bine setează întâi o parolă mai sus.',
  'settings.access.phrase.activate': 'Creează o frază',
  'settings.access.phrase.howStep1': 'Pe această instanță apasă „{button}“. Apar douăsprezece cuvinte.',
  'settings.access.phrase.howStep2': 'Deschide KnightLoader pe cealaltă mașină, intră pe aceeași pagină, apasă „{button}“ și scrie cele douăsprezece cuvinte.',
  'settings.access.phrase.howStep3': 'Gata! Fiecare instanță apare acum la cealaltă la „Instanțe” și poți conduce oricare de oriunde. Cu releul pornit, instanțele tale sunt accesibile din afara rețelei tale.',
  'settings.access.phrase.howWhat': 'Cuvintele sunt un secret, nu o adresă. Fiecare instanță scoate din ele două chei: una pentru a le găsi pe celelalte, una pentru criptare.\n\nCa să se găsească, fiecare instanță sună singură la același punct de întâlnire de pe internet. Cine arată aceeași cheie este pus în legătură. De aceea niciuna dintre instanțele tale nu trebuie să fie accesibilă din exterior.\n\nPunctul de întâlnire nu poate citi. Nu îți vede niciodată cuvintele, iar tot ce trece prin el este criptat cu a doua cheie.',
  'settings.access.phrase.statusDisconnected': 'Neconectat',
  'settings.access.phrase.statusHintProject': 'Conectat la releul proiectului. Accesul de la distanță este configurat.',
  'settings.access.phrase.statusHintOwn': 'Conectat la releul tău. Accesul de la distanță este configurat.',
  'settings.access.phrase.statusHintOff': 'Niciun releu activ. Instanțele tale sunt accesibile doar în rețeaua locală.',
  'settings.access.phrase.statusHintLost': 'Fără contact cu releul. KnightLoader încearcă în continuare. Până atunci instanțele se găsesc doar în rețeaua locală.',
  'settings.access.phrase.statusConnected': 'Conectat',
