  'settings.torrents.seedRatioHint': 'Continuă să facă seed la un torrent terminat până când acest raport, relativ la dimensiunea proprie, a fost redat rețelei. 0 = fără obiectiv de raport.',
  'settings.torrents.seedDuration': 'Durată de seed țintă',
  'settings.torrents.seedDurationHint': 'Continuă să facă seed la un torrent terminat atâta timp după finalizare. 0 = fără limită de timp. Oricare dintre cele două obiective de mai sus este atins primul oprește seedul.',
  'settings.torrents.seedDurationUnit': 'ore',
  'settings.torrents.transferTitle': 'Limită de transfer',
  'settings.torrents.uploadLimit': 'Limită de încărcare',
  'settings.torrents.uploadLimitHint': 'Limitează cât de rapid încarcă un torrent către rețea în timp ce face seed. 0 = nelimitat.',
  'settings.torrents.portTitle': 'Port și mapare',
  'settings.torrents.port': 'Port',
  'settings.torrents.portHint': 'Portul pe care această instanță ascultă conexiunile din rețea. 0 lasă motorul de torrente să aleagă unul.',
  'settings.torrents.portRestartHint': 'Motorul își construiește clientul de torrente o singură dată, deci un port nou intră în vigoare abia după ce această instanță repornește. Cererea către router de a-l mapa funcționează imediat, fie că un torrent ascultă deja pe el, fie că nu.',
  'settings.torrents.portMapHint': 'Cere routerului să redirecționeze portul de mai sus către acest computer prin UPnP, astfel încât peerii aflați în spatele altui router să îl poată atinge oricum. Nu orice router suportă asta, iar unele acceptă cererea fără ca aceasta să funcționeze cu adevărat.',
  'settings.torrents.portMapButton': 'Încearcă maparea UPnP',
  'settings.torrents.portMapping': 'Se întreabă routerul…',
  'settings.torrents.portMapNeedsPort': 'Setează mai sus un port înainte să-l mapezi. Cu 0, routerul nu are unde să redirecționeze.',
  'settings.torrents.portMapConfirmed': 'Confirmat: portul {port} este mapat și s-a verificat că este accesibil.',
  'settings.torrents.portMapUnconfirmed': 'Routerul a acceptat cererea, dar nu s-a putut confirma că maparea funcționează. Unele routere acceptă cererea în tăcere, fără s-o aplice. Încearcă o verificare a conectivității din afara rețelei.',
  'settings.torrents.portMapFailed': 'Portul nu a putut fi mapat: {error}',
  'settings.torrents.portMapUnavailable': 'Această versiune nu oferă încă mapare de port.',
  'settings.torrents.networkTitle': 'Descoperire de peeri',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Găsește peeri fără niciun tracker, folosind alți clienți BitTorrent ca registru distribuit.',
  'settings.torrents.pex': 'Schimb de peeri (PEX)',
  'settings.torrents.pexHint': 'Schimbă peerii cunoscuți cu cei deja conectați, astfel încât o rețea cu puțini peeri să fie găsită mai repede.',
  'settings.torrents.privateNote': 'Un torrent privat le dezactivează automat pe amândouă de îndată ce îi sunt cunoscute metadatele, indiferent de ce este setat aici: imediat pentru un fișier .torrent încărcat sau de îndată ce metadatele proprii ale unui link magnet sosesc din swarm. Majoritatea trackerelor private blochează conturile care folosesc oricare dintre ele.',
  'container.noJD': 'este criptat și doar un backend JDownloader îl poate deschide. Nu este configurat niciunul: setează KL_JD la un JDownloader pe care această instanță îl poate accesa, apoi repornește.',
  'container.jdOff': 'este criptat și doar backendul JDownloader îl poate deschide. „Backend JDownloader” este dezactivat pe pagina Module.',
  'torrent.staging': 'Se adaugă…',
  'torrent.staged': '{file} a fost adăugat în colector.',
  'torrent.stagedIn': '{file} a fost adăugat în colector în „{pkg}”.',
  'torrent.duplicate': '{file} este deja în listă.',
  'torrent.onlyOne': 'poate fi revizuit un singur .torrent odată',
  'torrent.tree.summary': '{n} din {total} fișier(e) selectat(e) ({size})',
  'torrent.tree.private': 'Tracker privat',
  'torrent.tree.selectAll': 'Selectează tot',
  'torrent.tree.selectNone': 'Deselectează tot',
  'torrent.tree.cancel': 'Anulează',
  'torrent.tree.add': 'Adaugă în colector',

  'settings.torrents.notApplied': 'Acest build nu aplică încă două dintre setările de mai jos. Limita de încărcare este salvată și verificată, dar motorul nu o poate aplica unei descărcări în curs. Nici DHT și PEX nu ajung la un torrent obișnuit: acesta face seed cu ambele pornite, orice ar fi setat aici. Un torrent privat funcționează altfel, cum explică (i) de la Descoperire de peeri.',
  'onboarding.step': 'Pasul {n} din {total}',
  'onboarding.skip': 'Sari peste',
  'onboarding.back': 'Înapoi',
  'onboarding.next': 'Următorul',
  'onboarding.finish': 'Gata',
  'onboarding.welcome.title': 'Bine ai venit în KnightLoader',
  'onboarding.welcome.body': 'KnightLoader este un manager de descărcări găzduit de tine. Lipește sau trage un link, iar backend-ul potrivit îl preia: motorul integrat pentru linkuri simple de fișiere, yt-dlp pentru pagini media, un serviciu debrid pentru hosterele pe care le plătești deja sau un JDownloader headless pentru tot restul. Acest tur scurt îți arată singura setare care merită verificată înainte să începi.',
  'onboarding.welcome.langLabel': 'Limba interfeței',
  'onboarding.folder.title': 'Unde ar trebui să ajungă fișierele?',
  'onboarding.folder.body': 'Acesta este dosarul în care sunt scrise descărcările terminate. Scrie o cale sau caută unul pe server. Îl poți schimba oricând din pagina de setări General.',
  'onboarding.accounts.title': 'Hosteri premium, oricând îi vrei',
  'onboarding.accounts.body': 'Coada funcționează complet fără cont. Când vrei viteză maximă la un hoster sau serviciu debrid pe care îl plătești deja, adaugă-i datele de autentificare la Conturi. Nimic din toate astea nu trebuie configurat acum.',
  'onboarding.accounts.link': 'Deschide Conturi',
  'onboarding.finished.title': 'Ești gata',
  'onboarding.finished.body': 'Cu asta se încheie turul. Pagina Ajutor din Setări are o prezentare completă a tot restul pe care îl face această versiune, iar majoritatea controalelor poartă propria explicație în spatele unei iconițe (i).',

