  'detail.label': 'Detaliile sarcinii',
  'detail.link': 'Link',
  'detail.address': 'Adresă',
  'detail.addressHint': 'Adresa de la care a fost pornită această descărcare. Este ceea ce a cerut aplicația, iar asta nu este întotdeauna și locul din care au venit octeții: printr-un serviciu debrid, hosterul de mai jos este site-ul pe care se află fișierul, iar backendul este cel care a adus-o.',
  'detail.copy': 'Copiază',
  'detail.copied': 'Copiat',
  'detail.copyFailed': 'Nu s-a copiat nimic.',
  'detail.origin': 'A intrat prin',
  'detail.originUnknown': 'Neconsemnat',
  'detail.package': 'Pachet',
  'detail.noPackage': 'În niciun pachet',
  'detail.onDisk': 'Acum pe disc',
  'detail.onDiskHint': 'Cât măsoară fișierul pe disc în această secundă, cerut serverului, nu numărat aici. O descărcare în curs crește de la o privire la alta, iar aceasta nu este dimensiunea anunțată de hoster.',
  'detail.mirrorOf': 'Copie de rezervă pentru',
  'detail.times': 'Marcaje de timp',
  'detail.timesHint': 'Când a sosit acest link, când s-a schimbat ultima dată și când s-a încheiat. Nu există un moment al pornirii transferului: aplicația nu l-a consemnat niciodată, iar unul ghicit din celelalte trei ar fi un număr după care oamenii chiar acționează.',
  'detail.nextTry': 'Următoarea încercare',
  'detail.stalledSince': 'Blocat din',
  'detail.retries': 'Reîncercări până acum',
  'detail.retriesHint': 'De câte ori a fost reîncercată această descărcare după o eroare. Contorul este pus înapoi la zero în clipa în care descărcarea se termină, deci un rând terminat arată zero chiar dacă a fost nevoie de patru încercări. Câte încercări au mai rămas nu se arată: plafonul depinde de cauză și de hoster, iar această pagină nu îl poate calcula.',
  'detail.stallRestarts': 'Reporniri după blocaj',
  'detail.stallRestartsHint': 'De câte ori a pornit din nou singură această descărcare supravegherea blocajelor. Este pus înapoi la zero când descărcarea se termină, la fel ca și contorul de mai sus.',
  'detail.failure': 'Ce nu a mers',
  'detail.cause': 'Cauză',
  'detail.message': 'Ce a spus backendul',
  'detail.messageHint': 'Propoziția venită de la ce a încercat să aducă fișierul, cuvânt cu cuvânt și netradusă. Este eroarea actuală și nimic altceva: o repornire o șterge, iar cele de dinainte nu sunt păstrate nicăieri.',
  'detail.heldBack': 'Reținut de',
  'detail.doing': 'Ce face acum',
  'detail.gaveUp': 'Nu se mai încearcă',
  'detail.gaveUpHint': 'Aici s-a oprit intenționat, nu fiindcă s-au terminat încercările: o captcha, un disc plin sau o regulă care spune „niciodată” pentru acest hoster. Creșterea numărului de reîncercări nu schimbă nimic aici. Marcajul în sine nu este scris în baza de date, deci după o repornire dispare, chiar dacă motivul lui rămâne.',
  'detail.rules': 'Regulile care au modelat asta',
  'detail.rulesHint': 'Regulile care s-au declanșat pe acest link când a fost pregătit, în ordinea în care au rulat. Sunt păstrate după nume, deci o regulă redenumită între timp nu mai este găsită, iar o regulă care nu a avut niciodată un nume este păstrată cu poziția pe care o avea atunci. Un clic pe una o deschide în editorul de reguli.',
  'detail.openRule': 'Deschide în editorul de reguli',
  'detail.noRules': 'Nicio regulă nu a atins acest link.',
  'detail.player': 'Redare',
  'detail.play': 'Redă aici',
  'detail.playHint': 'Redă fișierul direct de pe această instanță, fără să îl descarce a doua oară. Până apeși pe redare nu se aduce nimic, iar fișierul rămâne unde este.',
  'detail.playPartial': 'Această descărcare nu este terminată. Se poate reda doar partea aflată deja pe disc, saltul dincolo de ea nu merge, iar unele fișiere nu redau absolut nimic până nu ajunge ultimul octet.',
  'detail.playUnsupported': 'Acest browser nu poate reda acest fișier. Deschide-l sau salvează-l în schimb din meniul cu clic dreapta.',
  'detail.playRemote': 'Aici se redau doar fișierele aflate pe această instanță. O altă instanță își predă fișierele dintr-o bucată și fără salt, iar cu asta un player nu se descurcă.',
  'detail.playNotLocal': 'Această descărcare a fost adusă de JDownloader, deci fișierul stă pe discul acelui proces, nu pe acesta.',
