  'notifications.title': 'Notificări',
  'notifications.titleHint': 'Hotărăște pentru fiecare eveniment dacă apare ca un mesaj în aplicație, ca o notificare a sistemului tău de operare, sau deloc. O notificare de sistem ajunge la tine doar cât timp este deschisă o filă KnightLoader, iar modul silențios de mai jos se aplică oricum peste asta.',
