  'notifications.event.extractionFailed': 'Dezarhivare eșuată',
  'notifications.event.extractionFailedHint': 'O arhivă care s-a oprit fără să termine. De obicei lipsește parola, iar fișierele rămân pe loc până te ocupi de ele.',
  'notifications.event.captchaWaiting': 'O captcha așteaptă',
  'notifications.event.captchaWaitingHint': 'Fereastra captcha se deschide oricum în această filă. Pornește pe „Nu arăta nimic”, fiindcă fereastra aceea este deja mesajul, cât timp te uiți la ea. Pune-o pe notificare de sistem și o captcha dintr-o filă din fundal ajunge la tine înainte ca hosterul să arunce sesiunea.',
  'notifications.event.captchaFailed': 'Captcha eșuată',
  'notifications.event.captchaFailedHint': 'Nimeni nu a răspuns la timp, sau răspunsul nu a ajuns. Descărcarea din spatele ei rămâne pe loc.',
  'notifications.event.captchaResolved': 'Captcha rezolvată în altă parte',
