  'notifications.systemUnavailable': 'Notificările de sistem nu sunt disponibile aici: browserul tău le oferă doar prin HTTPS sau pe localhost. Tot ce este pe acest card se afișează oricum în aplicație.',
  'notifications.systemBlocked': 'Browserul tău blochează notificările pentru această adresă. Rândurile puse pe „Notificare de sistem” se afișează în schimb în aplicație, până le permiți din nou în setările de site ale browserului tău.',
  'notifications.systemNotGranted': 'Browserul nu a acordat permisiunea, deci acest eveniment rămâne în aplicație. Alege din nou „Notificare de sistem” ca să întrebi încă o dată.',
