  'task.retry.skipDetail': 'Pornește linkul imediat, în loc să pornească la capătul așteptării. Contorul merge mai departe: aceasta este reîncercarea care era oricum programată, nu una în plus.',
  'task.retry.skipFailed': 'Reîncercarea nu a putut fi pornită.',
