  'settings.health.nothingWaiting': 'Nu este reținut nimic.',
  'settings.health.nothingFailed': 'În listă nu a eșuat nimic.',
  'settings.health.scrapeHint': 'Deschide o a doua adresă care dă aceleași valori ca text simplu, în formatul pe care îl citesc Prometheus și uneltele construite după el. Ea este preluată, niciodată trimisă: nu pleacă nimic de pe această mașină câtă vreme nu vine monitorizarea ta aici să ceară. Cât timp asta este oprit, adresa nu există deloc și răspunde cu 404, exact ca orice altă adresă pe care această aplicație nu o are. Pe o instanță cu parolă, preluarea are nevoie de unul dintre tokenurile tale de API, iar asta se poate spune oricărui colector. Un colector nu trimite niciun antet de origine și trece deci; o filă de browser aflată pe altă adresă trimite unul și este refuzată când el nu se potrivește cu adresa acestei instanțe. În text stau căile dosarelor tale țintă. Dă-l deci numai acolo unde ai da și numele dosarelor.',
