  'settings.health.scrapeCopied': 'Adresă copiată',
  'settings.health.scrapeOffHint': 'Această adresă nu răspunde nimic cât timp comutatorul de mai sus este oprit.',
  'settings.diagnostics.systemTitle': 'Informații despre sistem',
  'settings.diagnostics.fileTitle': 'Fișier de jurnal',
  'settings.diagnostics.fileOn': 'Scrie jurnalul într-un fișier',
  'settings.diagnostics.fileOnHint': 'Oprit până îl pornești, iar o actualizare nu ți-l pornește niciodată. Pornit, această instanță scrie fiecare linie pe care o consemnează într-un fișier din dosarul ei de date, ca o prăbușire de alaltăieri să se mai poată citi după o repornire. O linie de jurnal poate numi adresa unui flux la care ești abonat, deci tratează fișierul ca pe al tău. Într-un container aceleași linii ajung oricum în docker logs; fișierul este ce rămâne după ce acelea au trecut mai departe.',
  'settings.diagnostics.fileSize': 'Dimensiune per fișier',
