  'settings.diagnostics.fileProblemSpace': 'Pe acel volum mai sunt {free} liberi.',
  'settings.diagnostics.fileProblemSpaceUnknown': 'Cât loc mai este liber pe acel volum nu se poate citi pe acest sistem.',
