  'settings.owner.identityTitle': 'Ca cine scrie această instanță',
  'settings.owner.identityHint': 'Fiecare fișier pe care îl creează această instanță primește acest proprietar și aceste drepturi, și la fel tot ce pornește ea: yt-dlp, ffmpeg și JDownloaderul livrat cu ea. Într-un container identitatea este fixată în clipa în care containerul pornește, de contul sub care a fost pornit, iar de pe această pagină nu se poate schimba nimic la ea.',
  'settings.owner.uid': 'Utilizator',
