  'settings.owner.envHow': 'Dacă vrei să ruleze sub alt cont, numește-l în comanda de pornire: --user <uid>:<gid>. Pe Unraid asta intră în Extra Parameters, iar containerul trebuie recreat ca să aibă efect.',
  'settings.owner.desktopNote': 'Aplicația desktop rulează sub propriul tău cont. PUID, PGID și UMASK sunt setări de container și aici nu fac nimic.',
  'settings.owner.noOwners': 'Pe acest sistem fișierele nu au proprietari, deci nu este nimic de comparat. Aceasta nu este o defecțiune.',
  'settings.owner.checkTitle': 'Verificarea dosarelor',
  'settings.owner.checkHint': 'Aici chiar se scrie câte un fișier și câte un subdosar în fiecare dosar, apoi se citește înapoi cui aparțin și cine altcineva le poate citi, iar amândouă se șterg la loc. Asta trebuie măsurat, nu calculat: o partajare poate aduce cu ea propriile reguli de drepturi, iar un dosar cu set-group-id pus dă alt grup decât cel pe care îl are acest proces. Verificarea rulează de la sine după ce salvezi un dosar schimbat, și de fiecare dată când apeși butonul.',
