  'settings.owner.v.ownerMismatch': 'Fișierele ajung aici ca {fileOwner}, dar dosarul aparține lui {dirOwner}. Cititul merge de obicei în continuare; redenumirea, mutarea și ștergerea de pe alt cont nu, iar tot ce se așteaptă ca dosarului să îi aparțină propriul conținut socotește aceste fișiere drept străine.',
  'settings.owner.v.groupUnreadable': 'Fișierele ajung aici cu {fileMode}, deci le poate deschide doar {fileOwner}. Ce rulează sub alt cont vede numele și nimic altceva.',
  'settings.owner.v.dirUnreadable': 'Subdosarele noi ajung aici cu {subdirMode}. Acolo nu intră nimeni în afară de {fileOwner}, indiferent ce permit fișierele din ele, și fiecare descărcare ajunge într-un astfel de dosar.',
