  'settings.selftest.accounts.advice.expired': 'Cheia este în regulă, abonamentul nu. Prelungește-l la furnizor.',
  'settings.selftest.accounts.advice.temp': 'Poate fi o limită, o pană la furnizor sau propria ta legătură. Se reîncearcă de la sine.',
  'settings.selftest.accounts.advice.error': 'Furnizorul numește ceva ce nu se rezolvă nici cu o cheie nouă, nici cu așteptarea, de exemplu o blocare a adresei tale.',
  'settings.selftest.accounts.readOnlyHint': 'Această verificare nu schimbă nimic la rutare. O autentificare care eșuează aici este raportată, nu pusă deoparte: un autotest rulat cu legătura căzută nu are voie să oprească fiecare cont pentru următorul sfert de oră.',
  'settings.selftest.relay': 'Releu',
  'settings.selftest.relay.off': 'Ai oprit releul, deci nu s-a apelat nimic.',
