  'settings.selftest.clock': 'Ceas și fus orar',
  'settings.selftest.clock.ok': 'Această mașină spune {time}, fusul {zone}.',
  'settings.selftest.clock.skew': 'Această mașină și browserul tău sunt la {skew} distanță.',
  'settings.selftest.clock.skewAdvice': 'Una dintre cele două merge greșit, iar această aplicație nu poate spune care. Un ceas atât de deviat face certificatele TLS să pară invalide și duce la respingerea tokenurilor debrid. Verifică întâi ceasul gazdei, containerul își ia ora de acolo.',
  'settings.selftest.clock.utc': 'Fusul orar este UTC, iar tu ai un program setat.',
  'settings.selftest.clock.utcAdvice': 'Programul merge pe ora locală a acestei mașini, iar fără TZ setat aceea este UTC. O fereastră pe care ai pus-o la 22:00 începe atunci la 22:00 UTC, adică la Berlin iarna la 23:00 și vara la miezul nopții. Pornește containerul cu TZ, de exemplu TZ=Europe/Berlin, și repornește-l.',
  'settings.selftest.clock.noZoneDB': 'TZ numește {zone}, iar baza de date a fusurilor nu a putut fi citită, de aceea fiecare oră din acest proces cade înapoi pe UTC.',
  'settings.selftest.torrentPort': 'Port torrent',
  'settings.selftest.torrentPort.noPort': 'Motorul de torrent își alege singur portul, iar acest build nu poate citi înapoi pe care l-a luat.',
  'settings.selftest.torrentPort.noPortAdvice': 'Pune un port fix pe pagina Torrenturi. Fără el nu este nimic de redirecționat și nimic de verificat, iar peerii aflați în spatele altui router ajung la tine doar dacă se conectează ei primii.',
  'settings.selftest.torrentPort.notChecked': 'Portul {port} este setat. Nu a fost întrebat nimic din afara acestei rețele, deci nu se știe dacă el este deschis din exterior.',
  'settings.selftest.torrentPort.notCheckedAdvice': 'Asta poate răspunde doar un calculator din afara propriei tale rețele, iar această aplicație nu contactează niciunul pe care nu l-ai ales tu. Butonul UPnP de pe pagina Torrenturi îi cere routerului tău să redirecționeze portul și îți spune dacă a putut confirma. Un port salvat după primul torrent al acestei rulări are efect abia după o repornire.',
  'settings.selftest.proxy.title': 'Proxy invers',
  'settings.selftest.proxy.hint': 'Ce spun browserul tău și această instanță, fiecare, despre exact aceeași cerere. Aceste patru lucruri se strică în spatele lui Nginx Proxy Manager și Traefik, iar trei dintre ele eșuează complet fără vreo eroare.',
  'settings.selftest.proxy.desktopSkip': 'Versiunea desktop își livrează singură interfața și nu are niciun proxy în față, deci aici nu este nimic de comparat.',
  'settings.selftest.proxy.host': 'Antetul Host',
  'settings.selftest.proxy.host.ok': 'Browserul și instanța sunt de acord că gazda este {host}.',
  'settings.selftest.proxy.host.rewritten': 'Browserul tău a cerut {browser}, acestei instanțe i s-a spus {server}.',
  'settings.selftest.proxy.host.rewrittenAdvice': 'Proxyul tău înlocuiește antetul Host. Această instanță compară Origin-ul browserului tău cu Host, de aceea fiecare scriere este refuzată cu 403 și vederea live nu se deschide niciodată, în timp ce pagina însăși se încarcă mai departe și arată bine. În Traefik lasă passHostHeader pornit. În nginx folosește proxy_set_header Host $host.',
  'settings.selftest.proxy.proto': 'Protocolul transmis mai departe',
  'settings.selftest.proxy.proto.ok': 'Proxyul spune https, și exact pe asta este browserul tău.',
  'settings.selftest.proxy.proto.direct': 'Ai ajuns direct la această instanță, deci nu există niciun proxy care ar trebui să declare ceva.',
  'settings.selftest.proxy.proto.missing': 'Browserul tău este pe https, iar proxyul nu a transmis asta mai departe.',
  'settings.selftest.proxy.proto.missingAdvice': 'Fără X-Forwarded-Proto, această instanță crede că a fost accesată prin http simplu. Codul QR și adresele de asociere de pe pagina Acces la distanță oferă atunci linkuri http://, iar un container predat lui JDownloader este preluat prin http. În nginx folosește proxy_set_header X-Forwarded-Proto $scheme; Traefik și Caddy îl setează singure.',
  'settings.selftest.proxy.prefix': 'Prefix de cale',
  'settings.selftest.proxy.prefix.underPath': 'Această instanță este livrată sub {path}.',
  'settings.selftest.proxy.ws': 'Trecere la WebSocket',
  'settings.selftest.proxy.ws.ok': 'Conexiunea live s-a deschis.',
  'settings.selftest.proxy.ws.failed': 'Conexiunea live nu s-a deschis.',
  'settings.selftest.proxy.ws.failedAdvice': 'Este cea mai frecventă defecțiune din spatele unui proxy, și nimic altceva nu ți-o arată: aplicația se reconectează în tăcere la nesfârșit, lista pur și simplu nu se mai mișcă, iar doar o reîncărcare a paginii arată ceva nou. În nginx, location are nevoie de proxy_http_version 1.1, proxy_set_header Upgrade $http_upgrade și proxy_set_header Connection "upgrade". Nginx Proxy Manager are la gazdă un comutator Websockets Support. Traefik și Caddy nu au nevoie de nimic.',
  'settings.diagnostics.startupTitle': 'Raport de pornire',
  'settings.diagnostics.startupHint': 'Ce a verificat această instanță o singură dată la pornire: programele pe care le apelează, fiecare dosar în care poate ajunge o descărcare și ceasul după care se citește un program. Este o citire, deci nimic de aici nu reține o descărcare și nu împiedică pornirea serverului. La pornire doar se uită; testul de scriere se face când apeși „Verifică din nou”.',
  'settings.diagnostics.startupTakenAt': 'Verificat la {when}, imediat după pornirea acestei instanțe.',
  'settings.diagnostics.startupJustChecked': 'Verificat chiar acum. Pachetul pe care îl descarci poartă în continuare măsurătoarea de la pornire, fiindcă de aceea are nevoie un raport de eroare.',
  'settings.diagnostics.startupRunning': 'Se verifică încă. Un dosar aflat pe o partajare care nu mai răspunde durează atât cât îi ia acelei partajări să renunțe.',
  'settings.diagnostics.startupOff': 'Verificarea este oprită pentru această instanță (KL_STARTUP_CHECK=0). Nu s-a privit nimic, iar asta nu este totuna cu „totul în regulă”.',
  'settings.diagnostics.startupNotRun': 'Acest build nu a rulat niciodată verificarea. Ea rulează în server și în aplicația desktop.',
  'settings.diagnostics.startupStatOnly': 'La pornire doar s-a privit: în niciun dosar nu s-a scris nimic. Un dosar marcat cu „În regulă” este deci un dosar care există, nu unul în care a scris această instanță.',
  'settings.diagnostics.startupNothingWrong': 'Aici nu este nimic de făcut.',
  'settings.diagnostics.startupRecheck': 'Verifică din nou',
  'settings.diagnostics.startupRechecking': 'Se verifică…',
  'settings.diagnostics.startupRecheckHint': 'Rulează acum aceleași verificări și scrie de data asta un mic fișier de test în fiecare dosar existent, pe care apoi îl șterge la loc. La pornire asta nu se face, fiindcă o scriere într-un dosar de pe array trezește discul pe care stă el, și asta la fiecare repornire. Pachetul pe care îl descarci păstrează măsurătoarea de la pornire, fiindcă de aceea are nevoie un raport de eroare.',
  'settings.diagnostics.startupRecheckFailed': 'Verificarea din nou a eșuat: {error}',
  'settings.diagnostics.startupNearest': 'cel mai apropiat dosar existent: {measured}',
