  'settings.resolvers.toolsOlder': 'Instalat este {current}, și acesta este mai nou decât cel mai nou release publicat ({latest}). Nu este nimic de făcut.',
  'settings.resolvers.toolsUnknown': 'Publicat este {latest}, instalat este {current}. Care dintre cele două este mai nou nu se poate citi din cele două șiruri de versiune, de aceea aici nu se afirmă nimic.',
  'settings.resolvers.toolsCheckFailed': 'GitHub nu a putut fi întrebat: {error}',
