  'auth.passkey.title': 'Chei de acces',
  'auth.passkey.hint': 'O cheie ținută de telefonul, laptopul sau stickul tău de securitate te conectează fără să scrii parola. Este o cale în plus înăuntru: parola rămâne valabilă, iar ștergerea tuturor cheilor nu blochează pe nimeni afară. O cheie de acces aparține adresei web pe care a fost creată, deci una înregistrată printr-un proxy nu merge pe adresa din rețeaua locală, și nici invers.',
  'auth.passkey.registered': '{n} înregistrate',
  'auth.passkey.none': 'Niciuna înregistrată',
  'auth.passkey.needsPassword': 'Pune mai întâi o parolă. O cheie de acces este a doua cale către o autentificare, deci trebuie să existe una.',
  'auth.passkey.unavailableTitle': 'Cheile de acces au nevoie de un nume de gazdă, iar această pagină este deschisă pe o adresă IP.',
  'auth.passkey.unavailableReason': 'O cheie de acces este legată de un domeniu, așa că browserele refuză tot schimbul pe o adresă goală și îl refuză din nou la un certificat în care nu au încredere. Ajunge la KnightLoader printr-un proxy invers sub un nume real cu certificat valid, deschide-l acolo și înregistrează cheia pe acea adresă.',
  'auth.passkey.noBrowserTitle': 'Acest browser nu oferă chei de acces.',
  'auth.passkey.noBrowserReason': 'Instanța nu are nimic în neregulă. Deschide-o într-un browser actual, sau pe un dispozitiv care poate păstra o cheie de acces, și butonul apare aici.',
  'auth.passkey.add': 'Configurează',
