  'auth.passkey.error.otherAddress': 'Această configurare a fost începută pe o altă adresă. Deschide KnightLoader pe adresa pe care ar trebui să funcționeze cheia și începe din nou acolo.',
  'settings.stall.reconnect': 'Deschide conexiuni noi pentru o descărcare blocată',
  'settings.stall.reconnectHint': 'Închide conexiunile unei descărcări marcate și deschide altele noi, care cer restul fișierului. Descărcarea păstrează ce a luat deja și își păstrează locul, de aceea opțiunea e activă până o dezactivezi. Un server care poate trimite fișierul doar întreg îl trimite din nou de la început. Fără asta, o descărcare al cărei server nu mai răspunde la jumătatea fișierului rămâne la 0 B/s până o pune cineva pe pauză. Cât timp descărcarea stă pe loc, asta se repetă de fiecare dată când expiră timpul setat mai sus. Dacă și „Repornește de la capăt o descărcare blocată” e activă, o descărcare care stă pe loc atât de mult și după conexiunile noi o ia de la capăt. Doar descărcările motorului integrat primesc conexiuni noi, inclusiv cele debrid și TorBox. JDownloader și yt-dlp își gestionează singure conexiunile, iar conexiunile noi nu ajută un torrent fără parteneri, așa că acestea sunt doar marcate.',
  'props.backend': 'Serviciu',
  'props.backendAuto': 'Automat',
  'props.backendHint': 'Ce serviciu descarcă aceste linkuri. „Automat” ia primul din ordinea de prioritate de pe pagina Conturi care poate prelua linkul în acel moment. Un link fixat merge doar la acel serviciu și eșuează cu motivul dacă serviciul nu îl poate prelua. O descărcare în curs își păstrează serviciul. Una pusă pe pauză se mută când o reiei și o ia acolo de la capăt.',
  'settings.globalSpeedLimit': 'Limită de viteză (0 = ∞)',
