  'rename.packageTitle': 'Redenumește pachetul',
  'rename.whenDone': 'Această descărcare încă rulează. Fișierul primește noul nume după ce se termină.',
  'rename.unpacking': 'Acest fișier se dezarhivează. Poate fi redenumit după ce se termină dezarhivarea.',
  'rename.remote': 'Motorul JDownloader descarcă acest fișier pe propria mașină și îi dă singur numele, așa că nu poate fi redenumit de aici.',
  'rename.torrent': 'Un torrent își numește singur fișierele, așa că nu poate fi redenumit.',
  'rename.volume': 'Acest fișier este o parte a unei arhive cu mai multe volume. Părțile își păstrează numele, altfel arhiva nu ar putea fi dezarhivată.',
  'rename.separator': 'Un nume nu poate conține / sau \\.',
  'rename.empty': 'Un nume nu poate fi gol.',
